(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-542":{scenario:{company:"Tân Việt Auto Components",supervisor:{name:"Ngô Thanh Tùng",role:{vi:"Trưởng phòng Chất lượng Nhà cung cấp",en:"Supplier Quality Manager"}},ref_code:"PPAP-3307",title:{vi:"Ppk không phải Pp. Phê duyệt phải có căn cứ.",en:"Ppk is not Pp. Approval needs evidence."},brief:{vi:"Nhà cung cấp nộp hồ sơ PPAP-3307 cho ống lót có đường kính lỗ 10.00 ± 0.20 mm (đặc tính đặc biệt). Nghiên cứu năng lực 125 mẫu: trung bình 10.06 mm, độ lệch chuẩn tổng thể 0.040 mm. Bản đánh giá nháp ghi Ppk 1.67 và đề xuất phê duyệt. Đối chiếu với quy tắc khách hàng, sửa chỉ số Ppk (làm tròn 2 chữ số) và trạng thái PPAP, rồi lập báo cáo có căn cứ.",en:"A supplier submitted PPAP-3307 for a bushing with bore diameter 10.00 ± 0.20 mm (special characteristic). The 125-piece capability study shows mean 10.06 mm and overall standard deviation 0.040 mm. The draft review states Ppk 1.67 and recommends approval. Check it against the customer rules, correct the Ppk (2 decimals) and the PPAP status, then write an evidence-based report."},reference_title:{vi:"Yêu cầu riêng của khách hàng về PPAP đã duyệt · PPAP-3307",en:"Approved customer-specific PPAP requirements · PPAP-3307"},fields:[{id:"PPAP_STATUS",label:{vi:"Trạng thái phê duyệt PPAP",en:"PPAP approval status"},initial:"APPROVED",expected:"REJECTED",choices:["APPROVED","INTERIM","REJECTED"],reference:"Quy tắc chấp nhận năng lực quá trình",hint:{vi:"Trạng thái phụ thuộc vào Ppk thật của quá trình, không phải số nhà cung cấp tự ghi.",en:"The status depends on the true process Ppk, not the figure the supplier wrote."}},{id:"PPK",label:{vi:"Chỉ số năng lực Ppk",en:"Performance index Ppk"},initial:"1.67",expected:"1.17",reference:"Bảng dữ liệu nghiên cứu năng lực",ref_value:{vi:"USL 10.20; LSL 9.80; trung bình 10.06; độ lệch chuẩn tổng thể 0.040; n = 125",en:"USL 10.20; LSL 9.80; mean 10.06; overall standard deviation 0.040; n = 125"},hint:{vi:"Chỉ số 1.67 bỏ qua việc quá trình lệch tâm; hãy xét khoảng cách từ trung bình tới giới hạn gần nhất.",en:"The 1.67 figure ignores the off-centre process; use the distance from the mean to the nearest limit."}}],sop32:{vi:"Ppk = min(USL - trung bình, trung bình - LSL) / (3 x độ lệch chuẩn tổng thể), làm tròn 2 chữ số. Quy tắc khách hàng (mô phỏng): Ppk ≥ 1.67 APPROVED; 1.33 ≤ Ppk < 1.67 INTERIM; Ppk < 1.33 REJECTED.",en:"Ppk = min(USL - mean, mean - LSL) / (3 x overall standard deviation), rounded to 2 decimals. Customer rule (training): Ppk ≥ 1.67 APPROVED; 1.33 ≤ Ppk < 1.67 INTERIM; Ppk < 1.33 REJECTED."},context:{label:"SQM PORTAL / PPAP-3307",metrics:[{label:{vi:"Dung sai",en:"Tolerance"},value:"10.00 ± 0.20 mm"},{label:{vi:"Trung bình mẫu",en:"Sample mean"},value:"10.06 mm"},{label:{vi:"Độ lệch chuẩn tổng thể",en:"Overall std deviation"},value:"0.040 mm"}]},crisis:{vi:"Giám đốc kinh doanh của nhà cung cấp gọi: “Anh ký APPROVED giúp em, tuần sau khách chạy xe mẫu rồi. Bên em mời anh sang tham quan nhà máy mẹ ở nước ngoài, mọi chi phí bên em lo.”",en:"The supplier's sales director calls: “Please sign APPROVED, the customer's prototype build is next week. We invite you to visit our parent plant abroad, all expenses on us.”"},options:{safe:{vi:"Từ chối chuyến đi theo quy định quà tặng, ghi Ppk 1.17 và REJECTED, yêu cầu kiểm 100% và kế hoạch cải tiến, báo trưởng phòng và khách hàng nếu ảnh hưởng tiến độ.",en:"Decline the trip under the gifts policy, record Ppk 1.17 and REJECTED, require 100% inspection and an improvement plan, and inform the manager and customer if timing is affected."},shortcut:{vi:"Ký APPROVED cho kịp xe mẫu, nhắc nhà cung cấp cải tiến sau.",en:"Sign APPROVED to make the prototype build and ask for improvement later."},wait:{vi:"Giữ hồ sơ trong hộp thư và chờ nhà cung cấp tự gửi số liệu mới.",en:"Leave the file in the inbox and wait for the supplier to send new data."}},questions:{vi:["Vì sao Ppk đúng là 1.17 chứ không phải 1.67? Quá trình đang lệch về phía nào và cần cải tiến gì?","Bạn bảo vệ khách hàng thế nào trong lúc chờ nhà cung cấp cải tiến, và xử lý lời mời tham quan ra sao?"],en:["Why is the correct Ppk 1.17 rather than 1.67? Which way is the process shifted and what must improve?","How do you protect the customer while the supplier improves, and how do you handle the trip invitation?"]},hints:{vi:["So số Ppk trên bản nháp với công thức Pp và Ppk; một chỉ số không tính tới vị trí trung bình.","Áp dụng SOP mục 3.2: tính khoảng cách tới USL và LSL, lấy giá trị nhỏ hơn chia cho 3 lần độ lệch chuẩn.","Đọc lại SOP mục 4.2: quyết định phê duyệt không được chịu ảnh hưởng của quà tặng hay lời mời."],en:["Compare the draft Ppk with the Pp and Ppk formulas; one index ignores where the mean sits.","Apply SOP 3.2: compute distances to USL and LSL and divide the smaller by 3 standard deviations.","Re-read SOP 4.2: approval decisions must not be influenced by gifts or invitations."]}},learning:{summary:{vi:"Kỹ sư Chất lượng Nhà cung cấp (SQE) bảo đảm linh kiện mua vào đạt yêu cầu ngay từ nguồn: đánh giá năng lực nhà cung cấp, duyệt hồ sơ PPAP, theo dõi chất lượng lô hàng, xử lý khiếu nại bằng 8D và thúc đẩy cải tiến liên tục. Công việc đòi hỏi vững thống kê, đo lường, hiểu quy trình sản xuất của nhà cung cấp và giữ sự độc lập, liêm chính trong mọi quyết định chấp nhận.",en:"A Supplier Quality Engineer (SQE) ensures purchased parts meet requirements at the source: auditing supplier capability, reviewing PPAP files, monitoring lot quality, handling complaints through 8D and driving continuous improvement. The role requires solid statistics and metrology, understanding of the supplier's processes and independence and integrity in every acceptance decision."},responsibilities:{vi:["Đánh giá, phê duyệt nhà cung cấp mới và đánh giá định kỳ quá trình sản xuất.","Duyệt hồ sơ PPAP: kết quả đo, nghiên cứu năng lực, MSA, PFMEA, kế hoạch kiểm soát.","Theo dõi chất lượng đầu vào, chỉ số PPM và xếp hạng nhà cung cấp.","Phát hành yêu cầu hành động khắc phục, giám sát báo cáo 8D và hiệu lực khắc phục.","Quản lý thay đổi từ nhà cung cấp và phối hợp phê duyệt lại khi cần."],en:["Assess and approve new suppliers and audit manufacturing processes periodically.","Review PPAP files: dimensional results, capability studies, MSA, PFMEA and control plans.","Monitor incoming quality, PPM metrics and supplier ratings.","Issue corrective action requests and oversee 8D reports and their effectiveness.","Manage supplier change notifications and coordinate requalification when needed."]},competencies:[{name:{vi:"Thống kê quá trình",en:"Process statistics"},desc:{vi:"Tính và diễn giải Cp, Cpk, Pp, Ppk, đọc biểu đồ kiểm soát và phân biệt biến động chung, đặc biệt.",en:"Calculate and interpret Cp, Cpk, Pp and Ppk, read control charts and separate common from special causes."}},{name:{vi:"Công cụ chất lượng ô tô",en:"Automotive core tools"},desc:{vi:"Vận dụng APQP, PPAP, FMEA, MSA, SPC theo yêu cầu khách hàng.",en:"Apply APQP, PPAP, FMEA, MSA and SPC to customer requirements."}},{name:{vi:"Đánh giá quá trình",en:"Process auditing"},desc:{vi:"Đánh giá tại xưởng nhà cung cấp, phát hiện điểm yếu kiểm soát và rủi ro.",en:"Audit supplier shop floors and find control weaknesses and risks."}},{name:{vi:"Giải quyết vấn đề",en:"Problem solving"},desc:{vi:"Dẫn dắt 8D, 5 Why, Ishikawa để tìm nguyên nhân gốc và ngăn tái diễn.",en:"Lead 8D, 5 Whys and Ishikawa to find root causes and prevent recurrence."}},{name:{vi:"Độc lập và liêm chính",en:"Independence and integrity"},desc:{vi:"Ra quyết định dựa trên dữ liệu, từ chối quà tặng và áp lực tiến độ không hợp lệ.",en:"Decide from data and refuse gifts and improper schedule pressure."}}],knowledge:{vi:["IATF 16949:2016 hệ thống quản lý chất lượng ngành ô tô, dựa trên ISO 9001:2015.","Sổ tay PPAP và APQP của AIAG, gồm 18 yếu tố hồ sơ PPAP và các mức nộp.","Sổ tay FMEA AIAG-VDA (2019) và phương pháp 7 bước.","Sổ tay MSA và SPC của AIAG: Gage R&R, biểu đồ kiểm soát, chỉ số năng lực.","ISO 2859-1 kế hoạch lấy mẫu kiểm tra theo thuộc tính dựa trên AQL."],en:["IATF 16949:2016 automotive quality management system, built on ISO 9001:2015.","AIAG PPAP and APQP manuals, including the 18 PPAP elements and submission levels.","AIAG-VDA FMEA Handbook (2019) and its 7-step approach.","AIAG MSA and SPC manuals: Gage R&R, control charts and capability indices.","ISO 2859-1 attribute sampling plans indexed by AQL."]},tools:["Phần mềm thống kê SPC","Máy đo tọa độ CMM","Cổng quản lý chất lượng nhà cung cấp","Biểu mẫu báo cáo 8D","Bộ dụng cụ đo cầm tay đã hiệu chuẩn"],kpis:{vi:["Tỷ lệ lỗi linh kiện đầu vào tính theo PPM.","Tỷ lệ hồ sơ PPAP được duyệt đúng hạn và đầy đủ.","Thời gian đóng 8D trung bình và tỷ lệ tái diễn lỗi.","Tỷ lệ nhà cung cấp đạt hạng A trong đánh giá định kỳ."],en:["Incoming part defect rate in PPM.","Share of PPAP files approved on time and complete.","Average 8D closure time and defect recurrence rate.","Share of suppliers rated A in periodic reviews."]},day:[{time:"08:00",vi:"Xem báo cáo kiểm tra đầu vào và các lô bị giữ lại trong đêm.",en:"Review incoming inspection results and lots put on hold overnight."},{time:"09:30",vi:"Duyệt hồ sơ PPAP: kiểm tra số liệu năng lực, MSA và kế hoạch kiểm soát.",en:"Review a PPAP file: capability data, MSA and the control plan."},{time:"11:00",vi:"Gọi trực tuyến với nhà cung cấp về tiến độ 8D của khiếu nại tháng trước.",en:"Call a supplier on 8D progress for last month's complaint."},{time:"13:30",vi:"Đánh giá quá trình tại xưởng nhà cung cấp, quan sát trạm kiểm soát đặc tính đặc biệt.",en:"Audit a supplier's process and observe special characteristic control stations."},{time:"16:30",vi:"Cập nhật xếp hạng nhà cung cấp và báo cáo rủi ro chất lượng cho trưởng phòng.",en:"Update supplier ratings and report quality risks to the manager."}],mistakes:{vi:["Nhầm Pp hoặc Cp với Ppk, Cpk nên không thấy quá trình lệch tâm.","Chấp nhận số liệu năng lực khi hệ thống đo chưa qua phân tích MSA.","Phê duyệt vì áp lực tiến độ mà không có biện pháp ngăn chặn hay chấp thuận sai lệch của khách hàng."],en:["Confusing Pp or Cp with Ppk or Cpk and missing an off-centre process.","Accepting capability data before the measurement system passed MSA.","Approving under schedule pressure without containment or a customer deviation approval."]},career:[{vi:"Kỹ thuật viên kiểm tra chất lượng đầu vào",en:"Incoming quality inspector"},{vi:"Kỹ sư chất lượng nhà cung cấp",en:"Supplier quality engineer"},{vi:"Trưởng nhóm chất lượng nhà cung cấp",en:"Supplier quality lead"},{vi:"Giám đốc chất lượng chuỗi cung ứng",en:"Supply chain quality director"}],glossary:[{term:"PPAP",vi:"Quy trình phê duyệt linh kiện sản xuất, chứng minh nhà cung cấp hiểu và đáp ứng yêu cầu ổn định.",en:"Production part approval process proving the supplier understands and consistently meets requirements."},{term:"Ppk",vi:"Chỉ số năng lực thực hiện dùng độ lệch chuẩn tổng thể và xét vị trí trung bình so với giới hạn.",en:"Performance index using overall standard deviation and the mean's position relative to the limits."},{term:"Pp",vi:"Chỉ số so sánh độ rộng dung sai với 6 lần độ lệch chuẩn tổng thể, không xét lệch tâm.",en:"Index comparing tolerance width with 6 overall standard deviations, ignoring centring."},{term:"8D",vi:"Phương pháp 8 bước giải quyết vấn đề từ lập nhóm, ngăn chặn đến ngăn tái diễn.",en:"Eight-discipline problem-solving method from team setup and containment to preventing recurrence."},{term:"PPM",vi:"Số phần triệu, đo số linh kiện lỗi trên một triệu linh kiện giao.",en:"Parts per million, counting defective parts per million delivered."}],quiz:[{q:{vi:"USL 20.5, LSL 19.5, trung bình 20.2, độ lệch chuẩn 0.1. Ppk bằng bao nhiêu?",en:"USL 20.5, LSL 19.5, mean 20.2, standard deviation 0.1. What is Ppk?"},options:{vi:["1.67","2.33","1.00","3.33"],en:["1.67","2.33","1.00","3.33"]},answer:2,explain:{vi:"Ppk = min(20.5 - 20.2, 20.2 - 19.5) / 0.3 = 0.3 / 0.3 = 1.00, thấp hơn ngưỡng chấp nhận.",en:"Ppk = min(20.5 - 20.2, 20.2 - 19.5) / 0.3 = 0.3 / 0.3 = 1.00, below the acceptance threshold."}},{q:{vi:"Nhà cung cấp mời bạn đi du lịch trong lúc bạn đang duyệt hồ sơ của họ. Bạn làm gì?",en:"A supplier invites you on a trip while you are reviewing their file. What do you do?"},options:{vi:["Nhận lời vì đó là văn hóa kinh doanh","Nhận nhưng không nói với ai","Hoãn duyệt hồ sơ cho đến sau chuyến đi","Từ chối, báo cáo theo quy định và duyệt dựa trên dữ liệu"],en:["Accept, it is business culture","Accept but tell no one","Delay the review until after the trip","Decline, report per policy and review on data"]},answer:3,explain:{vi:"Nhận lợi ích từ bên đang được đánh giá tạo xung đột lợi ích và làm mất tính độc lập.",en:"Taking benefits from a party under review creates a conflict of interest and destroys independence."}},{q:{vi:"Vì sao Ppk có thể thấp hơn nhiều so với Pp dù độ phân tán nhỏ?",en:"Why can Ppk be much lower than Pp even with low spread?"},options:{vi:["Vì quá trình lệch tâm so với giữa dung sai","Vì cỡ mẫu quá lớn","Vì dùng máy đo CMM","Vì dung sai quá rộng"],en:["Because the process is off the tolerance centre","Because the sample is too large","Because a CMM was used","Because the tolerance is too wide"]},answer:0,explain:{vi:"Ppk dùng khoảng cách tới giới hạn gần nhất nên phạt quá trình lệch tâm; Pp thì không.",en:"Ppk uses the distance to the nearest limit and penalises off-centre processes; Pp does not."}},{q:{vi:"Bước nào trong 8D phải làm ngay để bảo vệ khách hàng trước khi tìm nguyên nhân gốc?",en:"Which 8D step must happen immediately to protect the customer before finding the root cause?"},options:{vi:["Ghi nhận thành tích nhóm","Biện pháp ngăn chặn tạm thời","Chuẩn hóa tài liệu","Đánh giá chi phí"],en:["Recognise the team","Interim containment action","Standardise documents","Assess costs"]},answer:1,explain:{vi:"Ngăn chặn tạm thời như cách ly, phân loại 100% giúp lỗi không tới tay khách hàng.",en:"Interim containment such as quarantine and 100% sorting keeps defects from reaching the customer."}}],tools_en:["SPC statistical software","Coordinate measuring machine (CMM)","Supplier quality management portal","8D report template","Calibrated handheld measuring tools"]}}})})(window.KKR);
